const a = new Date("2026-03-01");
const b = new Date("2026-03-01");
console.log(a === b);                     // false: two different objects
console.log(a.getTime() === b.getTime()); // true: same moment
console.log(a < new Date("2026-04-01"));  // true: < and > compare the numbers

const msPerDay = 24 * 60 * 60 * 1000;
const days = (Date.parse("2026-03-10") - Date.parse("2026-03-01")) / msPerDay;
console.log(days); // 9

// Friendly formatting for people (uses their locale and zone)
console.log(new Date("2026-03-01T09:30:00Z").toLocaleDateString("en-GB")); // "01/03/2026"

const instant = new Date('2026-01-01T00:30:00Z');
const day = instant.toISOString().slice(0, 10);
// '2026-01-01' in UTC
